:root {
  --bg: #f5f6f8; --card: #ffffff; --ink: #1c2333; --muted: #6b7280;
  --line: #e5e7eb; --accent: #2f6df6; --accent-ink: #ffffff; --ok:#137a4b;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg); color: var(--ink); line-height: 1.45;
}
header { padding: 22px 20px 6px; max-width: 760px; margin: 0 auto; }
header h1 { margin: 0; font-size: 22px; }
header .mode { display:inline-block; margin-top:6px; font-size:12px; font-weight:600; color:var(--accent); background:#eaf1ff; padding:3px 10px; border-radius:999px; }
header p { margin: 6px 0 0; color: var(--muted); font-size: 14px; }
main { max-width: 760px; margin: 0 auto; padding: 0 20px 60px; }

.saver { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 16px; margin: 16px 0 26px; box-shadow: 0 1px 2px rgba(0,0,0,0.03); }
.saver label { font-size: 13px; color: var(--muted); display: block; margin-bottom: 6px; }
.saver-row { display: flex; gap: 8px; }
.saver input[type="url"] { flex: 1; padding: 11px 12px; font-size: 15px; border: 1px solid var(--line); border-radius: 8px; outline: none; }
.saver input[type="url"]:focus { border-color: var(--accent); }
.btn { border: none; background: var(--accent); color: var(--accent-ink); font-size: 15px; font-weight: 600; padding: 11px 18px; border-radius: 8px; cursor: pointer; white-space: nowrap; }
.btn.secondary { background:#eef1f6; color:#374151; }
.btn.small { padding:6px 12px; font-size:13px; }
.btn:disabled { opacity: .55; cursor: default; }
.hint { font-size: 12px; color: var(--muted); margin-top: 8px; }

.section-title { font-size: 13px; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin: 0 0 12px; }
.empty { text-align: center; color: var(--muted); padding: 40px 20px; border: 1px dashed var(--line); border-radius: 12px; background: #fafbfc; }

.card { display: flex; gap: 14px; background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 14px; margin-bottom: 12px; box-shadow: 0 1px 2px rgba(0,0,0,0.03); animation: pop .25s ease; }
@keyframes pop { from { transform: translateY(6px); opacity: 0; } to { transform: none; opacity: 1; } }
.thumb { width: 120px; height: 84px; flex: none; border-radius: 8px; background: #eef1f6; overflow: hidden; }
.thumb img { width: 100%; height: 100%; object-fit: cover; display:block; }
.card-body { flex: 1; min-width: 0; }
.card-title { font-size: 16px; font-weight: 600; margin: 0 0 3px; }
.card-site { font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: 6px; margin-bottom: 6px; }
.card-site img { width: 16px; height: 16px; border-radius: 4px; }
.card-desc { font-size: 14px; color: #384152; margin: 0 0 8px; }
.card-url { font-size: 12px; color: var(--accent); word-break: break-all; }
.card-meta { font-size: 12px; color: var(--muted); margin-top: 8px; }
.card-actions { margin-top:10px; display:flex; gap:8px; }

/* editing bits */
.edit-field { width:100%; font: inherit; padding:8px 10px; border:1px solid var(--accent); border-radius:6px; margin-bottom:8px; }
textarea.edit-field { min-height:64px; resize:vertical; }
.editable { cursor:text; border-radius:4px; padding:1px 3px; margin:-1px -3px; }
.editable:hover { background:#fff7d6; outline:1px dashed #e0c14a; }
.tag-hint { font-size:12px; color:var(--muted); margin-bottom:8px; }

/* review-before-save preview */
.preview { border:1px solid var(--accent); background:#f7faff; border-radius:12px; padding:14px; margin-bottom:12px; }
.preview .plabel { font-size:12px; font-weight:600; color:var(--accent); margin-bottom:10px; }

.skeleton { background: linear-gradient(90deg,#eef1f6,#f6f8fb,#eef1f6); border-radius: 6px; height: 12px; margin-bottom: 8px; }
.skeleton.w70 { width: 70%; } .skeleton.w40 { width: 40%; } .skeleton.w90 { width: 90%; }
.loading .thumb { animation: pulse 1.1s infinite; }
@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.55} }

/* tags + notes */
.tags { display:flex; flex-wrap:wrap; gap:6px; margin:2px 0 8px; }
