function findTagFilter(t){ return activeTags.find(f=>f.tag===t); }
function addTagFilter(t){ if(!findTagFilter(t)){activeTags.push({tag:t,mode:"include"});renderFilters();applyFilter();} }
function removeTagFilter(t){ const i=activeTags.findIndex(f=>f.tag===t); if(i>=0){activeTags.splice(i,1);renderFilters();applyFilter();} }
function toggleTagMode(t){ const f=findTagFilter(t); if(f){ f.mode=f.mode==="include"?"exclude":"include"; renderFilters(); applyFilter(); } }
function clearFilters(){ activeTags.length=0; if(searchEl)searchEl.value=""; renderFilters(); applyFilter(); }
function includeTags(){ return activeTags.filter(f=>f.mode==="include").map(f=>f.tag); }
function excludeTags(){ return activeTags.filter(f=>f.mode==="exclude").map(f=>f.tag); }
