      const a = n; n = (ctx) => a(ctx) && r(ctx);
    }
    return n;
  }
  function orExpr() {
    let n = andExpr();
    while (peek() && peek().t === "OR") {
      eat();
      const r = andExpr();
      const a = n; n = (ctx) => a(ctx) || r(ctx);
    }
    return n;
  }
