  const cookies = parseCookies(req);
  let sid = cookies.bmsid;
  if (!sid || !/^[a-f0-9]{32}$/.test(sid)) {
    sid = randomBytes(16).toString("hex");
    res.setHeader("Set-Cookie", `bmsid=${sid}; Path=/; HttpOnly; SameSite=Lax; Max-Age=31536000`);
  }
  return "u_" + sid;
}

