  capture(urlStr, id).then((copy) => {
    if (!copy) return;
    const acc = getAccount(userId);
    const b = acc.bookmarks.find((x) => x.id === id);
    if (b) { b.copy = copy; save(); }
  }).catch(() => {});
}

