:root {
  --bg:#f4f6f9; --card:#fff; --ink:#1b2230; --muted:#66707f; --line:#e4e8ee;
  --accent:#2f6df6; --accent-ink:#fff; --ok:#137a4b; --warn:#8a5b00; --danger:#d83a3f;
  --radius:12px; --shadow:0 1px 2px rgba(16,24,40,.04),0 1px 3px rgba(16,24,40,.06);
}
* { box-sizing:border-box; }
body { margin:0; background:var(--bg); color:var(--ink); line-height:1.45;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; }
.wrap { max-width:820px; margin:0 auto; padding:0 20px; }
