main.wrap { padding-bottom:80px; }

.btn { border:none; border-radius:8px; font-size:14px; font-weight:600; padding:9px 14px; cursor:pointer; background:#eef1f6; color:#374151; white-space:nowrap; }
.btn.primary { background:var(--accent); color:var(--accent-ink); }
