.btn.danger { background:var(--danger); color:#fff; }
.btn.small { padding:6px 11px; font-size:13px; }
.btn:disabled { opacity:.5; cursor:default; }

.hint { font-size:12px; color:var(--muted); margin:6px 0 0; }
.error-line { font-size:13px; color:#9a2b2b; background:#fdecec; border:1px solid #f2b8b8; border-radius:8px; padding:8px 12px; margin:8px 0 0; }
.warn-line { font-size:13px; color:var(--warn); background:#fff7e6; border:1px solid #f0d48a; border-radius:8px; padding:8px 12px; margin:8px 0 0; }

.saver { background:var(--card); border:1px solid var(--line); border-radius:var(--radius); padding:16px; margin:16px 0 22px; box-shadow:var(--shadow); }
.saver label { display:block; font-size:13px; color:var(--muted); margin-bottom:6px; }
.saver-row { display:flex; gap:8px; }
.saver input[type=url] { flex:1; padding:11px 12px; font-size:15px; border:1px solid var(--line); border-radius:8px; outline:none; }
.saver input:focus, #search:focus, .field input:focus, .field textarea:focus { border-color:var(--accent); }

.stage:empty { display:none; }
.stage { margin-bottom:18px; }

.toolbar { margin-bottom:16px; }
#search { width:100%; padding:11px 14px; font-size:15px; border:1px solid var(--line); border-radius:10px; outline:none; background:var(--card); }
