.skeleton { background:linear-gradient(90deg,#eef1f6,#f6f8fb,#eef1f6); border-radius:6px; height:12px; margin-bottom:8px; }
.skeleton.w70{width:70%} .skeleton.w90{width:90%} .skeleton.w40{width:40%}

body.text-sm main, body.text-sm .topbar { zoom:.9; }
body.text-lg main, body.text-lg .topbar { zoom:1.15; }

@media (max-width:560px) {
  .saver-row { flex-direction:column; }
  .thumb { width:92px; height:66px; }
  .controls { flex-direction:column; align-items:stretch; }
  .controls-right { justify-content:space-between; }
}

